@@ -3,9 +3,243 @@
  *
  * 需要实现并具名导出：
  *   export function nextRun(expr, fromEpochSec) { ... }
- *
- * 当前为未实现的桩代码。
  */
+const FIELD_DEFS = [
+  { name: "minute", min: 0, max: 59 },
+  { name: "hour", min: 0, max: 23 },
+  { name: "dom", min: 1, max: 31 },
+  { name: "month", min: 1, max: 12 },
+  { name: "dow", min: 0, max: 6 },
+];
+
+const MS_PER_DAY = 24 * 60 * 60 * 1000;
+const DAYS_PER_400_YEAR_CYCLE = 146097;
+
 export function nextRun(expr, fromEpochSec) {
-  throw new Error("not implemented");
+  const schedule = parseCron(expr);
+
+  if (typeof fromEpochSec !== "number" || !Number.isFinite(fromEpochSec)) {
+    throw new Error("fromEpochSec must be a finite number");
+  }
+
+  let candidateSec = Math.floor(fromEpochSec / 60) * 60;
+  if (candidateSec <= fromEpochSec) {
+    candidateSec += 60;
+  }
+
+  const start = new Date(candidateSec * 1000);
+  if (Number.isNaN(start.getTime())) {
+    throw new Error("fromEpochSec is outside the supported Date range");
+  }
+
+  const startDayMs = utcTime(
+    start.getUTCFullYear(),
+    start.getUTCMonth(),
+    start.getUTCDate(),
+    0,
+    0,
+    0,
+  );
+
+  for (let dayOffset = 0; dayOffset <= DAYS_PER_400_YEAR_CYCLE; dayOffset++) {
+    const dayMs = startDayMs + dayOffset * MS_PER_DAY;
+    const day = new Date(dayMs);
+    if (Number.isNaN(day.getTime())) {
+      break;
+    }
+    if (!matchesDate(day, schedule)) {
+      continue;
+    }
+
+    const startHour = dayOffset === 0 ? start.getUTCHours() : 0;
+    const startMinute = dayOffset === 0 ? start.getUTCMinutes() : 0;
+    const time = firstTimeOnDay(
+      schedule.hour.values,
+      schedule.minute.values,
+      startHour,
+      startMinute,
+    );
+
+    if (time) {
+      return Math.trunc(dayMs / 1000) + time.hour * 3600 + time.minute * 60;
+    }
+  }
+
+  throw new Error(
+    "cron expression has no matching time in a 400-year Gregorian cycle",
+  );
+}
+
+function parseCron(expr) {
+  if (typeof expr !== "string") {
+    throw new Error("cron expression must be a string");
+  }
+
+  const trimmed = expr.trim();
+  if (trimmed === "") {
+    throw new Error("cron expression must contain 5 fields");
+  }
+
+  const fields = trimmed.split(/\s+/);
+  if (fields.length !== 5) {
+    throw new Error("cron expression must contain 5 fields");
+  }
+
+  const parsed = {};
+  for (let i = 0; i < FIELD_DEFS.length; i++) {
+    parsed[FIELD_DEFS[i].name] = parseField(fields[i], FIELD_DEFS[i]);
+  }
+  return parsed;
+}
+
+function parseField(field, def) {
+  if (field === "") {
+    throw new Error(`${def.name} field must not be empty`);
+  }
+
+  const allowed = new Array(def.max + 1).fill(false);
+  const items = field.split(",");
+  for (const item of items) {
+    if (item === "") {
+      throw new Error(`${def.name} field contains an empty list item`);
+    }
+    addFieldItem(allowed, item, def);
+  }
+
+  const values = [];
+  for (let value = def.min; value <= def.max; value++) {
+    if (allowed[value]) {
+      values.push(value);
+    }
+  }
+
+  if (values.length === 0) {
+    throw new Error(`${def.name} field does not allow any values`);
+  }
+
+  return {
+    allowed,
+    values,
+    unrestricted: field === "*",
+  };
+}
+
+function addFieldItem(allowed, item, def) {
+  const slashParts = item.split("/");
+  if (slashParts.length > 2) {
+    throw new Error(`${def.name} field contains too many "/" characters`);
+  }
+
+  const base = slashParts[0];
+  if (base === "") {
+    throw new Error(`${def.name} field has an empty step base`);
+  }
+
+  let step = 1;
+  const hasStep = slashParts.length === 2;
+  if (hasStep) {
+    step = parsePositiveInteger(slashParts[1], `${def.name} step`);
+  }
+
+  const range = parseBaseRange(base, def, hasStep);
+  for (let value = range.start; value <= range.end; value += step) {
+    allowed[value] = true;
+  }
+}
+
+function parseBaseRange(base, def, hasStep) {
+  if (base === "*") {
+    return { start: def.min, end: def.max };
+  }
+
+  const dashParts = base.split("-");
+  if (dashParts.length > 2) {
+    throw new Error(`${def.name} field contains too many "-" characters`);
+  }
+
+  if (dashParts.length === 2) {
+    if (dashParts[0] === "" || dashParts[1] === "") {
+      throw new Error(`${def.name} range endpoint must not be empty`);
+    }
+    const start = parseFieldNumber(dashParts[0], def);
+    const end = parseFieldNumber(dashParts[1], def);
+    if (start > end) {
+      throw new Error(
+        `${def.name} range start must be less than or equal to range end`,
+      );
+    }
+    return { start, end };
+  }
+
+  const value = parseFieldNumber(base, def);
+  return { start: value, end: hasStep ? def.max : value };
+}
+
+function parseFieldNumber(raw, def) {
+  const value = parseNonNegativeInteger(raw, `${def.name} value`);
+  if (value < def.min || value > def.max) {
+    throw new Error(`${def.name} value ${value} is outside ${def.min}-${def.max}`);
+  }
+  return value;
+}
+
+function parsePositiveInteger(raw, label) {
+  const value = parseNonNegativeInteger(raw, label);
+  if (value <= 0) {
+    throw new Error(`${label} must be a positive integer`);
+  }
+  return value;
+}
+
+function parseNonNegativeInteger(raw, label) {
+  if (!/^\d+$/.test(raw)) {
+    throw new Error(`${label} must be an integer`);
+  }
+  return Number(raw);
+}
+
+function matchesDate(day, schedule) {
+  const month = day.getUTCMonth() + 1;
+  if (!schedule.month.allowed[month]) {
+    return false;
+  }
+
+  const domMatches = Boolean(schedule.dom.allowed[day.getUTCDate()]);
+  const dowMatches = Boolean(schedule.dow.allowed[day.getUTCDay()]);
+
+  if (!schedule.dom.unrestricted && !schedule.dow.unrestricted) {
+    return domMatches || dowMatches;
+  }
+  return domMatches && dowMatches;
+}
+
+function firstTimeOnDay(hours, minutes, startHour, startMinute) {
+  for (const hour of hours) {
+    if (hour < startHour) {
+      continue;
+    }
+
+    const minMinute = hour === startHour ? startMinute : 0;
+    const minute = firstValueAtLeast(minutes, minMinute);
+    if (minute !== undefined) {
+      return { hour, minute };
+    }
+  }
+  return undefined;
+}
+
+function firstValueAtLeast(values, minimum) {
+  for (const value of values) {
+    if (value >= minimum) {
+      return value;
+    }
+  }
+  return undefined;
+}
+
+function utcTime(year, monthIndex, day, hour, minute, second) {
+  const date = new Date(0);
+  date.setUTCFullYear(year, monthIndex, day);
+  date.setUTCHours(hour, minute, second, 0);
+  return date.getTime();
 }

diff --git a/src/decimal.mjs b/src/decimal.mjs
index a7be2d1..e053497 100644
--- a/src/decimal.mjs
+++ b/src/decimal.mjs
@@ -8,10 +8,78 @@
  * 输入为十进制字符串，返回规范化的十进制字符串。详见任务说明。
  * 当前为未实现的桩代码。
  */
+const DECIMAL_PATTERN = /^[+-]?(?:\d+(?:\.\d*)?|\.\d+)$/;
+
+function parseDecimal(value) {
+  if (typeof value !== "string" || !DECIMAL_PATTERN.test(value)) {
+    throw new Error("invalid decimal string");
+  }
+
+  let text = value;
+  let sign = 1n;
+
+  if (text[0] === "+" || text[0] === "-") {
+    sign = text[0] === "-" ? -1n : 1n;
+    text = text.slice(1);
+  }
+
+  const dotIndex = text.indexOf(".");
+  const integerPart = dotIndex === -1 ? text : text.slice(0, dotIndex);
+  const fractionalPart = dotIndex === -1 ? "" : text.slice(dotIndex + 1);
+  const digits = `${integerPart}${fractionalPart}`.replace(/^0+/, "") || "0";
+  const integer = BigInt(digits) * sign;
+
+  return {
+    integer,
+    scale: fractionalPart.length,
+  };
+}
+
+function pow10(exponent) {
+  return 10n ** BigInt(exponent);
+}
+
+function formatDecimal(integer, scale) {
+  if (integer === 0n) {
+    return "0";
+  }
+
+  const negative = integer < 0n;
+  let digits = (negative ? -integer : integer).toString();
+
+  if (scale === 0) {
+    return `${negative ? "-" : ""}${digits}`;
+  }
+
+  if (digits.length <= scale) {
+    digits = `${"0".repeat(scale - digits.length + 1)}${digits}`;
+  }
+
+  const splitAt = digits.length - scale;
+  const integerPart = digits.slice(0, splitAt);
+  const fractionalPart = digits.slice(splitAt).replace(/0+$/, "");
+
+  if (fractionalPart === "") {
+    return `${negative ? "-" : ""}${integerPart}`;
+  }
+
+  return `${negative ? "-" : ""}${integerPart}.${fractionalPart}`;
+}
+
 export function add(a, b) {
-  throw new Error("not implemented");
+  const left = parseDecimal(a);
+  const right = parseDecimal(b);
+  const scale = Math.max(left.scale, right.scale);
+  const sum =
+    left.integer * pow10(scale - left.scale) +
+    right.integer * pow10(scale - right.scale);
+
+  return formatDecimal(sum, scale);
 }

 export function mul(a, b) {
-  throw new Error("not implemented");
+  const left = parseDecimal(a);
+  const right = parseDecimal(b);
+
+  return formatDecimal(left.integer * right.integer, left.scale + right.scale);
 }

diff --git a/src/dijkstra.mjs b/src/dijkstra.mjs
index b3ce9f2..55b2a0f 100644
--- a/src/dijkstra.mjs
