@@ -7,7 +7,232 @@
  * 详见任务说明。当前为未实现的桩代码。
  */
 export function shortestPath(n, edges, src, dst) {
-  throw new Error("not implemented");
+  validateGraphInput(n, edges, src, dst);
+
+  const edgeMaps = Array.from({ length: n }, () => new Map());
+  for (const [u, v, w] of edges) {
+    const previous = edgeMaps[u].get(v);
+    if (previous === undefined || w < previous) {
+      edgeMaps[u].set(v, w);
+    }
+  }
+
+  if (src === dst) {
+    return { dist: 0, path: [src] };
+  }
+
+  const reverse = Array.from({ length: n }, () => []);
+  for (let u = 0; u < n; u += 1) {
+    for (const [v, w] of edgeMaps[u]) {
+      reverse[v].push([u, w]);
+    }
+  }
+
+  const distanceToDst = dijkstra(reverse, dst);
+  if (distanceToDst[src] === Infinity) {
+    return null;
+  }
+
+  const tightAdj = Array.from({ length: n }, () => []);
+  for (let u = 0; u < n; u += 1) {
+    if (distanceToDst[u] === Infinity) {
+      continue;
+    }
+
+    for (const [v, w] of edgeMaps[u]) {
+      if (distanceToDst[v] !== Infinity && distanceToDst[u] === w + distanceToDst[v]) {
+        tightAdj[u].push(v);
+      }
+    }
+    tightAdj[u].sort((a, b) => a - b);
+  }
+
+  const visited = new Uint8Array(n);
+  const seen = new Uint32Array(n);
+  const stack = [];
+  let seenMark = 0;
+
+  const canReachDst = (start) => {
+    if (start === dst) {
+      return true;
+    }
+    if (visited[start]) {
+      return false;
+    }
+
+    if (seenMark === 0xffffffff) {
+      seen.fill(0);
+      seenMark = 0;
+    }
+    seenMark += 1;
+
+    stack.length = 0;
+    stack.push(start);
+    seen[start] = seenMark;
+
+    while (stack.length > 0) {
+      const u = stack.pop();
+      for (const v of tightAdj[u]) {
+        if (visited[v]) {
+          continue;
+        }
+        if (v === dst) {
+          return true;
+        }
+        if (seen[v] !== seenMark) {
+          seen[v] = seenMark;
+          stack.push(v);
+        }
+      }
+    }
+
+    return false;
+  };
+
+  const path = [src];
+  visited[src] = 1;
+
+  let current = src;
+  while (current !== dst) {
+    let next = -1;
+    for (const v of tightAdj[current]) {
+      if (!visited[v] && canReachDst(v)) {
+        next = v;
+        break;
+      }
+    }
+
+    if (next === -1) {
+      return null;
+    }
+
+    path.push(next);
+    visited[next] = 1;
+    current = next;
+  }
+
+  return { dist: distanceToDst[src], path };
 }

 export default shortestPath;
+
+function validateGraphInput(n, edges, src, dst) {
+  if (!Number.isInteger(n) || n <= 0) {
+    throw new TypeError("n must be a positive integer");
+  }
+  validateNode(src, n, "src");
+  validateNode(dst, n, "dst");
+
+  if (!Array.isArray(edges)) {
+    throw new TypeError("edges must be an array");
+  }
+
+  for (const edge of edges) {
+    if (!Array.isArray(edge) || edge.length !== 3) {
+      throw new TypeError("each edge must be a [u, v, w] tuple");
+    }
+
+    const [u, v, w] = edge;
+    validateNode(u, n, "edge endpoint u");
+    validateNode(v, n, "edge endpoint v");
+    if (!Number.isInteger(w) || w < 0) {
+      throw new TypeError("edge weight w must be a non-negative integer");
+    }
+  }
+}
+
+function validateNode(value, n, name) {
+  if (!Number.isInteger(value) || value < 0 || value >= n) {
+    throw new RangeError(`${name} must be an integer in [0, n - 1]`);
+  }
+}
+
+function dijkstra(adj, source) {
+  const dist = new Array(adj.length).fill(Infinity);
+  const heap = new MinHeap();
+
+  dist[source] = 0;
+  heap.push(source, 0);
+
+  while (heap.size > 0) {
+    const item = heap.pop();
+    if (item.dist !== dist[item.node]) {
+      continue;
+    }
+
+    for (const [next, weight] of adj[item.node]) {
+      const nextDist = item.dist + weight;
+      if (nextDist < dist[next]) {
+        dist[next] = nextDist;
+        heap.push(next, nextDist);
+      }
+    }
+  }
+
+  return dist;
+}
+
+class MinHeap {
+  #items = [];
+
+  get size() {
+    return this.#items.length;
+  }
+
+  push(node, dist) {
+    const item = { node, dist };
+    this.#items.push(item);
+    this.#bubbleUp(this.#items.length - 1);
+  }
+
+  pop() {
+    const first = this.#items[0];
+    const last = this.#items.pop();
+
+    if (this.#items.length > 0) {
+      this.#items[0] = last;
+      this.#bubbleDown(0);
+    }
+
+    return first;
+  }
+
+  #bubbleUp(index) {
+    while (index > 0) {
+      const parent = Math.floor((index - 1) / 2);
+      if (this.#items[parent].dist <= this.#items[index].dist) {
+        break;
+      }
+
+      this.#swap(parent, index);
+      index = parent;
+    }
+  }
+
+  #bubbleDown(index) {
+    while (true) {
+      const left = index * 2 + 1;
+      const right = left + 1;
+      let smallest = index;
+
+      if (left < this.#items.length && this.#items[left].dist < this.#items[smallest].dist) {
+        smallest = left;
+      }
+      if (right < this.#items.length && this.#items[right].dist < this.#items[smallest].dist) {
+        smallest = right;
+      }
+      if (smallest === index) {
+        break;
+      }
+
+      this.#swap(index, smallest);
+      index = smallest;
+    }
+  }
+
+  #swap(a, b) {
+    const temp = this.#items[a];
+    this.#items[a] = this.#items[b];
+    this.#items[b] = temp;
+  }
+}

diff --git a/src/md.mjs b/src/md.mjs
index be2c233..5215bd5 100644
--- a/src/md.mjs
+++ b/src/md.mjs
@@ -1,11 +1,265 @@
+const ESCAPABLE = new Set(["*", "_", "`", "[", "]", "\\", "(", ")"]);
+const NO_POS = -1;
+
+function isEscapable(ch) {
+  return ESCAPABLE.has(ch);
+}
+
+function escapeHtmlChar(ch) {
+  if (ch === "&") return "&amp;";
+  if (ch === "<") return "&lt;";
+  if (ch === ">") return "&gt;";
+  return ch;
+}
+
+function escapeHtmlText(text) {
+  let out = "";
+  for (let i = 0; i < text.length; i += 1) {
+    out += escapeHtmlChar(text[i]);
+  }
+  return out;
+}
+
+function escapeUrlChar(ch) {
+  if (ch === "&") return "&amp;";
+  if (ch === "<") return "&lt;";
+  if (ch === ">") return "&gt;";
+  if (ch === '"') return "&quot;";
+  return ch;
+}
+
+function buildMeta(md) {
+  const n = md.length;
+  const escaped = new Uint8Array(n);
+  const inCode = new Uint8Array(n);
+  const codeEnd = new Int32Array(n);
+  codeEnd.fill(NO_POS);
+
+  for (let i = 0; i < n; ) {
+    const ch = md[i];
+
+    if (ch === "\\" && i + 1 < n && isEscapable(md[i + 1])) {
+      escaped[i + 1] = 1;
+      i += 2;
+      continue;
+    }
+
+    if (ch === "`") {
+      const close = md.indexOf("`", i + 1);
+      if (close !== NO_POS) {
+        codeEnd[i] = close;
+        inCode.fill(1, i, close + 1);
+        i = close + 1;
+        continue;
+      }
+    }
+
+    i += 1;
+  }
+
+  const bracketEnd = new Int32Array(n);
+  const parenEnd = new Int32Array(n);
+  bracketEnd.fill(NO_POS);
+  parenEnd.fill(NO_POS);
+
+  const bracketStack = [];
+  for (let i = 0; i < n; i += 1) {
+    if (codeEnd[i] !== NO_POS) {
+      i = codeEnd[i];
+      continue;
+    }
+    if (inCode[i] || escaped[i]) continue;
+
+    if (md[i] === "[") {
+      bracketStack.push(i);
+    } else if (md[i] === "]" && bracketStack.length > 0) {
+      bracketEnd[bracketStack.pop()] = i;
+    }
+  }
+
+  const parenEscaped = new Uint8Array(n);
+  for (let i = 0; i < n; ) {
+    if (md[i] === "\\" && i + 1 < n && isEscapable(md[i + 1])) {
+      parenEscaped[i + 1] = 1;
+      i += 2;
+    } else {
+      i += 1;
+    }
+  }
+
+  const parenStack = [];
+  for (let i = 0; i < n; i += 1) {
+    if (parenEscaped[i]) continue;
+
+    if (md[i] === "(") {
+      parenStack.push(i);
+    } else if (md[i] === ")" && parenStack.length > 0) {
+      parenEnd[parenStack.pop()] = i;
+    }
+  }
+
+  const nextStar = new Int32Array(n + 1);
+  const nextUnderscore = new Int32Array(n + 1);
+  const nextStrongStar = new Int32Array(n + 1);
+  const nextStrongUnderscore = new Int32Array(n + 1);
+  nextStar.fill(n);
+  nextUnderscore.fill(n);
+  nextStrongStar.fill(n);
+  nextStrongUnderscore.fill(n);
+
+  for (let i = n - 1; i >= 0; i -= 1) {
+    nextStar[i] = nextStar[i + 1];
+    nextUnderscore[i] = nextUnderscore[i + 1];
+    nextStrongStar[i] = nextStrongStar[i + 1];
+    nextStrongUnderscore[i] = nextStrongUnderscore[i + 1];
+
+    if (inCode[i] || escaped[i]) continue;
+
+    if (md[i] === "*") {
+      nextStar[i] = i;
+      if (i + 1 < n && !inCode[i + 1] && md[i + 1] === "*") {
+        nextStrongStar[i] = i;
+      }
+    } else if (md[i] === "_") {
+      nextUnderscore[i] = i;
+      if (i + 1 < n && !inCode[i + 1] && md[i + 1] === "_") {
+        nextStrongUnderscore[i] = i;
+      }
+    }
+  }
+
+  return {
+    escaped,
+    codeEnd,
+    bracketEnd,
+    parenEnd,
+    nextStar,
+    nextUnderscore,
+    nextStrongStar,
+    nextStrongUnderscore,
+  };
+}
+
 /**
  * 行内 Markdown 转 HTML。
  *
- * 需要实现具名导出：
- *   export function renderInline(md) -> string
- *
- * 详见任务说明。当前为未实现的桩代码。
+ * @param {string} md
+ * @returns {string}
  */
 export function renderInline(md) {
-  throw new Error("not implemented");
+  if (typeof md !== "string") {
+    throw new TypeError("renderInline expects a string");
+  }
+  if (md === "") return "";
+
+  const meta = buildMeta(md);
+
+  function findEmphasisClose(ch, len, from, end) {
+    let pos;
+    if (len === 2) {
+      pos = ch === "*" ? meta.nextStrongStar[from] : meta.nextStrongUnderscore[from];
+      return pos + 1 < end ? pos : NO_POS;
+    }
+
+    pos = ch === "*" ? meta.nextStar[from] : meta.nextUnderscore[from];
+    return pos < end ? pos : NO_POS;
+  }
+
+  function renderUrl(start, end) {
+    let out = "";
+
+    for (let i = start; i < end; ) {
+      if (md[i] === "\\" && i + 1 < end && isEscapable(md[i + 1])) {
+        out += escapeUrlChar(md[i + 1]);
